using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.BuildingBlocks.Application.Security;using Mbb.Archive.Modules.Archive.Application.Abstractions;namespace Mbb.Archive.Modules.Archive.Application.Records.Get;public sealed class GetArchiveRecordQueryHandler:IQueryHandler<GetArchiveRecordQuery,ArchiveRecordDetails>{private readonly IArchiveQueries _queries;private readonly ICurrentUserScope _scope;public GetArchiveRecordQueryHandler(IArchiveQueries queries,ICurrentUserScope scope){_queries=queries;_scope=scope;}public async Task<Result<ArchiveRecordDetails>> Handle(GetArchiveRecordQuery q,CancellationToken ct){var r=await _queries.GetAsync(q.Id,await _scope.GetAsync(ct),ct);// Kapsam dışı kayıt da 404 döner: 403 kaydın varlığını sızdırır.
        return r is null?Result<ArchiveRecordDetails>.Failure(Error.NotFound("archive.record_not_found","Archive record was not found.")):Result<ArchiveRecordDetails>.Success(r);}}
